    function isCurrentUserMatch() {
        if (!ENABLE_USER_CHECK) return true;
        const currentUserElement = document.querySelector('a.mau');
        return currentUserElement?.textContent.trim() === TARGET_USER_NAME;
    }

    // ==========================================
    // CÁC HÀM TIỆN ÍCH DÙNG CHUNG
    // ==========================================
    function isElementVisible(el) {
        if (!el) return false;
        const hasShowClass = el.classList.contains('show');
        const isDisplayBlock = window.getComputedStyle(el).display !== 'none';
        return hasShowClass || el.offsetParent !== null || isDisplayBlock;
    }

    function getFirstAvailableValue(selectors) {
        for (const selector of selectors) {
            const el = document.querySelector(selector);
            const val = el ? (el.value || el.textContent || '').trim() : '';
            if (val) return val;
        }
        return '';
    }

    function setFieldValue(selectorOrEl, val) {
        if (val === undefined || val === null) return;
        const el = typeof selectorOrEl === 'string' ? document.querySelector(selectorOrEl) : selectorOrEl;
        if (!el) return;

        el.value = val;
        el.dispatchEvent(new Event('input', { bubbles: true }));
        el.dispatchEvent(new Event('change', { bubbles: true }));

        if (window.jQuery) {
            const $el = window.jQuery(el);$el.trigger('input').trigger('change');
            if ($el.data('select2')) {$el.val(val).trigger('change');
            }
        }
    }

    function getFormFieldValueByLabel(labelKey) {
        const label = document.querySelector(`label[id$="-${labelKey}"], label[for$="-${labelKey}"]`);
        if (label) {
            const targetId = label.getAttribute('for');
            if (targetId) {
                const inputEl = document.getElementById(targetId);
                if (inputEl && (inputEl.value || inputEl.textContent)) {
                    return (inputEl.value || inputEl.textContent).trim();
                }
            }
            const parentComponent = label.closest('.formio-component') || label.parentElement;
            if (parentComponent) {
                const el = parentComponent.querySelector('input, textarea');
                if (el && el.value) return el.value.trim();
            }
        }

        const directEl = document.querySelector(`[name="data[${labelKey}]"], input[id$="-${labelKey}"], textarea[id$="-${labelKey}"]`);
        if (directEl && directEl.value) {
            return directEl.value.trim();
        }

        return '';
    }

    // ==========================================
    // MODULE 1: CHỌN BÁC SĨ (HSBA)
    // ==========================================
    function autoSelectDoctor() {
        if (!isCurrentUserMatch()) return;

        const modal = document.querySelector(CONFIG.doctor.modalSelector);
        const doctorSelect = document.querySelector(CONFIG.doctor.selectSelector);

        const isModalOpen = modal && (modal.offsetParent !== null || window.getComputedStyle(modal).display !== 'none');
        if (!isModalOpen || !doctorSelect) return;

        if (doctorSelect.value === TARGET_DOCTOR_VALUE) return;

        doctorSelect.value = TARGET_DOCTOR_VALUE;
        doctorSelect.dispatchEvent(new Event('change', { bubbles: true }));

        if (window.jQuery) {
            const $select = window.jQuery(doctorSelect);
            if ($select.data('select2')) {$select.val(TARGET_DOCTOR_VALUE).trigger('change');
            }
        }
    }

    // ==========================================
    // MODULE 2: TRÍCH XUẤT CLIPBOARD & TỔNG HỢP TÓM TẮT BỆNH ÁN
    // ==========================================
    async function getClipboardText() {
        if (navigator.clipboard && navigator.clipboard.readText) {
            try {
                return await navigator.clipboard.readText();
            } catch (e) {
                console.warn('[Module 2] Lỗi truy cập Clipboard:', e);
            }
        }
        return '';
    }

    async function executeMedicalRecordExtraction() {
        if (!isCurrentUserMatch()) return;

        // BƯỚC 1: TRÍCH XUẤT TỪ CLIPBOARD
        const text = await getClipboardText();
        if (text) {
            const upperText = text.toUpperCase();

            const getValue = (startKeys, endKeys, cleanNewlines = true) => {
                const sKeys = Array.isArray(startKeys) ? startKeys : [startKeys];
                const eKeys = Array.isArray(endKeys) ? endKeys : [endKeys];

                let startIdx = -1;
                let matchedStartKey = '';

                for (const key of sKeys) {
                    const idx = upperText.indexOf(key.toUpperCase());
                    if (idx !== -1 && (startIdx === -1 || idx < startIdx)) {
                        startIdx = idx;
                        matchedStartKey = key;
                    }
                }

                if (startIdx === -1) return '';
                const contentStart = startIdx + matchedStartKey.length;

                let endIdx = -1;
                for (const key of eKeys) {
                    const idx = upperText.indexOf(key.toUpperCase(), contentStart);
                    if (idx !== -1 && (endIdx === -1 || idx < endIdx)) {
                        endIdx = idx;
                    }
                }

                if (endIdx === -1) return '';
                let result = text.substring(contentStart, endIdx).trim();
                result = result.replace(/^[:\-\s\u00a0]+/, '');

                return cleanNewlines ? result.replace(/\r?\n|\r/g, ' ') : result;
            };

            const benhSuVal = getValue(["BỆNH SỬ:"], ["TIỀN SỬ:"]);
            const tienSuVal = getValue(["TIỀN SỬ:"], ["KHÁM"]);
            const khamVal = getValue(["KHÁM"], ["Tim"], false); // Giữ nguyên xuống dòng

            if (benhSuVal) setFieldValue(CONFIG.medicalRecord.fields.benhSu, benhSuVal);
            if (tienSuVal) setFieldValue(CONFIG.medicalRecord.fields.tienSu, tienSuVal);
            if (khamVal) setFieldValue(CONFIG.medicalRecord.fields.khamToanThan, khamVal);

            const machRaw = getValue(["Mạch", "M"], ["lần/phút", "l/p"]);
            const machVal = machRaw.replace(/[^0-9]/g, '');
            if (machVal) setFieldValue(CONFIG.medicalRecord.fields.mach, machVal);

            const haRaw = getValue(["Huyết áp", "HA:", "HA"], ["mmHg"]);
            const haClean = haRaw.replace(/[:\s\u00a0]/g, '');
            if (haClean) {
                const haParts = haClean.split('/');
                if (haParts[0]) setFieldValue(CONFIG.medicalRecord.fields.haTren, haParts[0].replace(/[^0-9]/g, ''));
                if (haParts[1]) setFieldValue(CONFIG.medicalRecord.fields.haDuoi, haParts[1].replace(/[^0-9]/g, ''));
            }

            const nhietDoRaw = getValue(["Nhiệt độ", "NĐ"], ["độ c", "°c", "oc"]);
            const nhietDoVal = nhietDoRaw.replace(/[:\s\u00a0]/g, '').replace(/,/g, '.');
            if (nhietDoVal) setFieldValue(CONFIG.medicalRecord.fields.nhietDo, nhietDoVal);

            const nhipThoRaw = getValue(["Nhịp Thở", "NT"], ["lần/", "lần/phút", "l/p"]);
            const nhipThoVal = nhipThoRaw.replace(/[:\s\u00a0]/g, '').replace(/[^0-9]/g, '');
            if (nhipThoVal) setFieldValue(CONFIG.medicalRecord.fields.nhipTho, nhipThoVal);
        }

        // BƯỚC 2: TỔNG HỢP TÓM TẮT BỆNH ÁN
        const multiInfoEl = document.querySelector(CONFIG.medicalRecord.multiInfoSelector);
        const infoText = multiInfoEl ? (multiInfoEl.innerText || multiInfoEl.textContent || '') : '';

        let gender = 'nam';
        const genderMatch = infoText.match(/Giới\s*tính\s*:\s*([^\n\r,;]+)/i);
        if (genderMatch && genderMatch[1]) {
            const rawG = genderMatch[1].trim().toLowerCase();
            gender = rawG.includes('nữ') ? 'nữ' : 'nam';
        }

        let age = '';
        const currentYear = new Date().getFullYear();
        const birthMatch = infoText.match(/Năm\s*sinh\s*:\s*(\d{4})/i);
        if (birthMatch && birthMatch[1]) {
            const birthYear = parseInt(birthMatch[1], 10);
            if (!isNaN(birthYear) && birthYear > 1900 && birthYear <= currentYear) {
                age = currentYear - birthYear;
            }
        }

        const lyDoVaoVien = getFormFieldValueByLabel('LYDOVAOVIEN');
        const khamToanThan = getFormFieldValueByLabel('KHAMTOANTHAN');
        const tuanHoan = getFormFieldValueByLabel('TUANHOAN');
        const hoHap = getFormFieldValueByLabel('HOHAP');
        const tieuHoa = getFormFieldValueByLabel('TIEUHOA');

        const line1 = `Bệnh nhân ${gender} ${age ? age + ' tuổi ' : ''}vào viện vì ${lyDoVaoVien} qua thăm khám hiện ghi nhận:`;
        const line2 = `- ${khamToanThan}`;

        const line3Parts = [];
        if (tuanHoan) line3Parts.push(tuanHoan);
        if (hoHap) line3Parts.push(hoHap);
        if (tieuHoa) line3Parts.push(tieuHoa);
        const line3 = `- ${line3Parts.join('; ')};`;

        const summaryText = `${line1}\n${line2}\n${line3}\n`;

        let tomtatInput = document.querySelector(CONFIG.medicalRecord.tomTatBaSelector);
        if (!tomtatInput) {
            const tomtatLabel = document.querySelector('label[id$="-TOMTATBA"], label[for$="-TOMTATBA"]');
            if (tomtatLabel) {
                const targetId = tomtatLabel.getAttribute('for');
                if (targetId) tomtatInput = document.getElementById(targetId);
                if (!tomtatInput) {
                    const comp = tomtatLabel.closest('.formio-component') || tomtatLabel.parentElement;
                    tomtatInput = comp?.querySelector('textarea, input');
                }
            }
        }

        if (tomtatInput) {
            setFieldValue(tomtatInput, summaryText);
            const origBorder = tomtatInput.style.border;
            tomtatInput.style.border = '2px solid #28a745';
            setTimeout(() => { tomtatInput.style.border = origBorder; }, 1200);
        }
    }

    /**
     * TẠO GIAO DIỆN TRỢ LÝ: BANNER NOTI & NÚT TRÒN "i" PHÍA TRÊN LABEL LÝ DO VÀO VIỆN
     */
    function injectAssistantButton() {
        if (!isCurrentUserMatch()) return;

        const lyDoLabel = document.querySelector(CONFIG.medicalRecord.lyDoVaoVienLabelSelector);
        if (!lyDoLabel) return;

        // Tránh chèn trùng lặp
        if (document.getElementById('his-assistant-wrapper')) return;

        const wrapper = document.createElement('div');
        wrapper.id = 'his-assistant-wrapper';
        wrapper.className = 'w-full mb-2 flex items-center justify-between p-2.5 rounded-lg border border-blue-200 bg-blue-50 text-blue-900 shadow-sm transition-all duration-300';
        wrapper.style.cssText = 'display: flex; align-items: center; justify-content: space-between; padding: 10px 14px; margin-bottom: 8px; border-radius: 8px; border: 1px solid #bfdbfe; background-color: #eff6ff; color: #1e3a8a; box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05); font-size: 13px; line-height: 1.4;';

        const notiSpan = document.createElement('span');
        notiSpan.id = 'his-assistant-noti';
        notiSpan.className = 'flex-1 pr-3 font-normal text-xs md:text-sm';
        notiSpan.style.cssText = 'flex: 1; padding-right: 12px; font-weight: 500; font-size: 12.5px;';
        notiSpan.textContent = CONFIG.medicalRecord.noti1;

        // Nút tròn chữ "i" màu xanh dương
        const btnI = document.createElement('button');
        btnI.id = 'his-assistant-btn-i';
        btnI.type = 'button';
        btnI.className = 'flex-shrink-0 w-8 h-8 rounded-full bg-blue-600 hover:bg-blue-700 active:bg-blue-800 text-white font-bold italic shadow flex items-center justify-center transition cursor-pointer select-none';
        btnI.style.cssText = 'flex-shrink: 0; width: 32px; height: 32px; min-width: 32px; border-radius: 9999px; background-color: #2563eb; color: #ffffff; font-weight: bold; font-family: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif; font-style: italic; font-size: 17px; display: flex; align-items: center; justify-content: center; border: none; cursor: pointer; box-shadow: 0 2px 4px rgba(37, 99, 235, 0.3); transition: background-color 0.2s, transform 0.1s;';
        btnI.textContent = 'i';
        btnI.title = 'Bấm để tự động điền bệnh án từ clipboard';

        btnI.addEventListener('mouseenter', () => { btnI.style.backgroundColor = '#1d4ed8'; });
        btnI.addEventListener('mouseleave', () => { btnI.style.backgroundColor = '#2563eb'; });
        btnI.addEventListener('mousedown', () => { btnI.style.transform = 'scale(0.95)'; });
        btnI.addEventListener('mouseup', () => { btnI.style.transform = 'scale(1)'; });

        // Xử lý sự kiện click nút "i"
        btnI.addEventListener('click', async (e) => {
            e.preventDefault();
            e.stopPropagation();

            btnI.disabled = true;
            btnI.style.opacity = '0.6';
            btnI.textContent = '...';

            try {
                // Kích hoạt chuỗi xử lý trích xuất & tổng hợp
                await executeMedicalRecordExtraction();

                // Cập nhật giao diện sang Noti 2 (thông báo hoàn tất màu xanh lá)
                notiSpan.textContent = CONFIG.medicalRecord.noti2;
                wrapper.style.borderColor = '#bbf7d0';
                wrapper.style.backgroundColor = '#f0fdf4';
                wrapper.style.color = '#14532d';
                btnI.style.backgroundColor = '#16a34a';
                btnI.title = 'Đã hoàn tất điền bệnh án!';
            } catch (err) {
                console.error('[Module 2] Lỗi khi xử lý:', err);
            } finally {
                btnI.disabled = false;
                btnI.style.opacity = '1';
                btnI.textContent = 'i';
            }
        });

        wrapper.appendChild(notiSpan);
        wrapper.appendChild(btnI);

        // Chèn ngay phía trên nhãn Lý do vào viện
        lyDoLabel.parentNode.insertBefore(wrapper, lyDoLabel);
    }

    // ==========================================
    // MODULE 3: DINH DƯỠNG TRÊN 18
    // ==========================================
    function handleNutritionForm() {
        if (!isCurrentUserMatch()) return;

        const modal = document.querySelector(CONFIG.nutrition.modalSelector);
        if (!isElementVisible(modal)) {
            if (modal?.dataset.nutritionAutoFilled) {
                delete modal.dataset.nutritionAutoFilled;
            }
            return;
        }

        if (modal.dataset.nutritionAutoFilled === 'true') return;

        const form = modal.querySelector(CONFIG.nutrition.formSelector) || document.querySelector(CONFIG.nutrition.formSelector);
        if (!form) return;

        const defaultEntries = Object.entries(CONFIG.nutrition.defaults);
        const isDomReady = defaultEntries.some(([id]) => form.querySelector(`#${id}`) !== null);
        if (!isDomReady) return;

        defaultEntries.forEach(([id, val]) => {
            const selectEl = form.querySelector(`#${id}`);
            if (selectEl) setFieldValue(selectEl, val);
        });

        Object.entries(CONFIG.nutrition.priorityInputs).forEach(([targetId, sourceSelectors]) => {
            const targetInput = form.querySelector(`#${targetId}`);
            if (targetInput) {
                const matchedValue = getFirstAvailableValue(sourceSelectors);
                if (matchedValue) setFieldValue(targetInput, matchedValue);
            }
        });

        modal.dataset.nutritionAutoFilled = 'true';
    }

    // ==========================================
    // MODULE 4: CAM KẾT PT/GMHS
    // ==========================================
    const selectChoiceByText = async (modal, name, searchText) => {
        const select = modal.querySelector(`select[name="data[${name}]"], select[id$="-${name}"]`);
        if (!select) return false;

        const container = select.closest('.choices') || select.parentElement;
        if (!container) return false;

        container.scrollIntoView({ block: 'nearest' });

        container.click();
        await new Promise(r => setTimeout(r, 400));

        const activeDropdowns = modal.querySelectorAll('.choices__list--dropdown.is-active');
        let targetItem = null;

        activeDropdowns.forEach(dropdown => {
            const items = dropdown.querySelectorAll('.choices__item--choice');
            items.forEach(item => {
                if (item.textContent.trim().includes(searchText)) {
                    targetItem = item;
                }
            });
        });

        if (targetItem) {
            const events = ['mousedown', 'mouseup', 'click'];
            events.forEach(ev => {
                targetItem.dispatchEvent(new MouseEvent(ev, {
                    bubbles: true,
                    cancelable: true,
                    view: window
                }));
            });
            await new Promise(r => setTimeout(r, 150));
            return true;
        } else {
            container.click();
            return false;
        }
    };

    async function setChoicesMultipleOrSingle(modal, fieldName, values, textList, isMultiple = false) {
        const select = modal.querySelector(`select[name="data[${fieldName}]"], select[id$="-${fieldName}"]`);
        if (!select) return;

        let allSuccess = true;
        for (const text of textList) {
            const ok = await selectChoiceByText(modal, fieldName, text);
            if (!ok) allSuccess = false;
        }

        if (!allSuccess) {
            const container = select.closest('.choices') || select.parentElement;
            const choicesInstance = select.choices || container?.choices || select._choices;

            Array.from(select.options).forEach(opt => {
                if (values.includes(opt.value)) opt.selected = true;
            });
            if (!isMultiple && values[0]) select.value = values[0];

            if (choicesInstance && typeof choicesInstance.setChoiceByValue === 'function') {
                try {
                    if (isMultiple) {
                        choicesInstance.removeActiveItems();
                        choicesInstance.setChoiceByValue(values);
                    } else {
                        choicesInstance.setChoiceByValue(values[0]);
                    }
                } catch (e) {}
            }

            select.dispatchEvent(new Event('input', { bubbles: true }));
            select.dispatchEvent(new Event('change', { bubbles: true }));
        }
    }

    function applyCurrentDateToFlatpickr(modal) {
        const hiddenInput = modal.querySelector('input[name="data[NGAY_TAO_PHIEU]"], input[id$="-NGAY_TAO_PHIEU"]');
        if (!hiddenInput) return;

        const inputGroup = hiddenInput.closest('.input-group') || hiddenInput.parentElement;
        const visibleInput = inputGroup ? inputGroup.querySelector('input.form-control.input, input[type="text"]:not([type="hidden"])') : null;

        const fp = hiddenInput._flatpickr || visibleInput?._flatpickr || inputGroup?._flatpickr;

        const now = new Date();
        const pad = n => String(n).padStart(2, '0');
        const d = pad(now.getDate());
        const m = pad(now.getMonth() + 1);
        const y = now.getFullYear();
        const hr = pad(now.getHours());
        const mi = pad(now.getMinutes());
        const sc = pad(now.getSeconds());

        const isoVal = `${y}-${m}-${d} ${hr}:${mi}:${sc}`;
        const displayVal = `${d}/${m}/${y} ${hr}:${mi}`;

        if (fp && typeof fp.setDate === 'function') {
            fp.setDate(now, true);
        }

        hiddenInput.value = isoVal;
        hiddenInput.dispatchEvent(new Event('input', { bubbles: true }));
        hiddenInput.dispatchEvent(new Event('change', { bubbles: true }));

        if (visibleInput) {
            visibleInput.value = displayVal;
            visibleInput.dispatchEvent(new Event('input', { bubbles: true }));
            visibleInput.dispatchEvent(new Event('change', { bubbles: true }));
        }

        if (window.jQuery) {
            window.jQuery(hiddenInput).trigger('change');
            if (visibleInput) window.jQuery(visibleInput).trigger('change');
        }
    }

    async function handleProcedureConsentForm() {
        if (!isCurrentUserMatch()) return;

        const modal = document.querySelector(CONFIG.procedure.modalSelector);
        if (!isElementVisible(modal)) {
            if (modal?.dataset.procedureAutoFilled) {
                delete modal.dataset.procedureAutoFilled;
            }
            delete modal?.dataset.procedureProcessing;
            return;
        }

        if (modal.dataset.procedureAutoFilled === 'true' || modal.dataset.procedureProcessing === 'true') {
            return;
        }

        const selectLoaiGiay = modal.querySelector('select[name="data[LOAIGIAYCK]"], select[id$="-LOAIGIAYCK"]');
        if (!selectLoaiGiay) return;

        modal.dataset.procedureProcessing = 'true';

        try {
            await new Promise(resolve => setTimeout(resolve, 1000));

            let loaiGiaySuccess = await selectChoiceByText(modal, 'LOAIGIAYCK', CONFIG.procedure.emergencySearchText);
            await selectChoiceByText(modal, 'BACSIPT', CONFIG.procedure.doctorSearchText);

            const matchedIcd = getFirstAvailableValue(CONFIG.procedure.prioritySources.icd);
            const matchedChanDoan = getFirstAvailableValue(CONFIG.procedure.prioritySources.chandoan);

            if (matchedIcd) {
                const icdInput = modal.querySelector('[name="data[ICD_CHANDOAN]"], input[id$="-ICD_CHANDOAN"]');
                setFieldValue(icdInput, matchedIcd);
            }

            if (matchedChanDoan) {
                const chanDoanInput = modal.querySelector('[name="data[TENICD_CHANDOAN]"], input[id$="-TENICD_CHANDOAN"]');
                setFieldValue(chanDoanInput, matchedChanDoan);
            }

            const fullDiagnosisTextarea = modal.querySelector('textarea[name="data[CHANDOAN]"], textarea[id$="-CHANDOAN"]');
            if (fullDiagnosisTextarea) {
                let combinedText = '';
                if (matchedIcd && matchedChanDoan) {
                    combinedText = `${matchedIcd} - ${matchedChanDoan}`;
                } else {
                    combinedText = matchedIcd || matchedChanDoan || '';
                }
                if (combinedText) {
                    setFieldValue(fullDiagnosisTextarea, combinedText);
                }
            }

            for (const item of CONFIG.procedure.choicesFieldDefaults) {
                await setChoicesMultipleOrSingle(modal, item.name, item.values, item.textList, item.isMultiple);
            }

            await selectChoiceByText(modal, 'DAIDIEN', CONFIG.procedure.representativeSearchText);
            applyCurrentDateToFlatpickr(modal);

            if (!loaiGiaySuccess) {
                await new Promise(resolve => setTimeout(resolve, 300));
                loaiGiaySuccess = await selectChoiceByText(modal, 'LOAIGIAYCK', CONFIG.procedure.emergencySearchText);
            }

            modal.dataset.procedureAutoFilled = 'true';
        } catch (err) {
            console.error('[Module 4] Lỗi khi điền tự động:', err);
        } finally {
            delete modal.dataset.procedureProcessing;
        }
    }

    // ==========================================
    // THEO DÕI VÀ KÍCH HOẠT (MUTATION OBSERVER)
    // ==========================================
    const observer = new MutationObserver(() => {
        if (!isCurrentUserMatch()) return;

        autoSelectDoctor();           // Module 1
        injectAssistantButton();      // Module 2 UI
        handleNutritionForm();        // Module 3
        handleProcedureConsentForm(); // Module 4
    });

    observer.observe(document.body, {
        childList: true,
        subtree: true,
        attributes: true,
        attributeFilter: ['style', 'class']
    });

    if (isCurrentUserMatch()) {
        autoSelectDoctor();
        injectAssistantButton();
        handleNutritionForm();
        handleProcedureConsentForm();
    }
})();

// ==UserScript==
// @name         Deep Indigo
// @namespace    http://tampermonkey.net/
// @version      1.0.0
// @description  Nhấn Option + Shift + L (Mac) hoặc Alt + Shift + L (Win) để mở link Drive trong tab mới
// @author       You
// @match        *://*/*
// @grant        none
// @run-at       document-idle
// ==/UserScript==

(function () {
  'use strict';

  const TARGET_URL = 'https://drive.google.com/file/d/1_h7Jrs6aFSoZ7uKNOrF40pO99dS2jC5u/view?usp=sharing';

  window.addEventListener('keydown', function (e) {
    // Kiểm tra tổ hợp: Alt/Option + Shift + L
    // Sử dụng e.code === 'KeyL' để nhận diện phím L bất kể kiểu gõ tiếng Việt (Telex/VNI) hay trạng thái Caps Lock
    if (e.altKey && e.shiftKey && (e.code === 'KeyL' || e.key.toLowerCase() === 'l')) {
      e.preventDefault();  // Ngăn chặn các hành vi mặc định của trình duyệt nếu có
      e.stopPropagation();

      window.open(TARGET_URL, '_blank', 'noopener,noreferrer');
    }
  }, true);
})();

// ==UserScript==
// @name         Sunset Orange
// @version      2.9.4
// @description  In Phiếu Theo Dõi Điều Trị
// @match        *://*/*web_his*
// @run-at       document-idle
// @grant        none
// ==/UserScript==

(function() {
    'use strict';

    // ==========================================
    // 0. ĐIỀU KIỆN THỰC THI (GUARD CLAUSE)
    // ==========================================
    function checkDoctorPermission() {
        const mauLinks = document.querySelectorAll('a.mau');
        for (const link of mauLinks) {
            if (link.textContent.trim().includes('Phan Đình Huy')) {
                return true;
            }
        }
        return false;
    }

    let isInitialized = false;

    function initScriptIfPermitted() {
        if (isInitialized) return;

        if (!checkDoctorPermission()) {
            return;
        }

        isInitialized = true;
        console.log("%c[HIS PĐT] Đã xác thực <a class='mau'>Phan Đình Huy</a>. Script khởi chạy thành công!", "color: #06d6a0; font-weight: bold;");

        setupScriptFeatures();
    }

    // ==========================================
    // 1. TOÀN BỘ LOGIC KHI ĐÃ ĐẠT ĐIỀU KIỆN
    // ==========================================
    function setupScriptFeatures() {
        // --- 1.1 TẠO / HỦY Ô TICK BẰNG DOUBLE CLICK & PHÍM TẮT ---
        function toggleRowCheckbox(row) {
            if (!row) return;

            const targetTd = row.querySelector('td[aria-describedby="list_phieudieutri_GIOLAP_TDT"]');
            if (!targetTd) return;

            const existingCheckbox = targetTd.querySelector('.final-tick-box, .injected-tick-box');
            if (existingCheckbox) {
                existingCheckbox.remove();
                return;
            }

            const checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.className = 'final-tick-box injected-tick-box';
            checkbox.checked = true;
            checkbox.style.display = 'block';
            checkbox.style.margin = '8px auto 2px auto';
            checkbox.style.width = '18px';
            checkbox.style.height = '18px';
            checkbox.style.cursor = 'pointer';

            checkbox.addEventListener('click', function(ev) {
                ev.stopPropagation();
            });

            targetTd.appendChild(checkbox);
        }

        // Double-click vào hàng
        document.addEventListener('dblclick', function(e) {
            const row = e.target.closest('tr[role="row"]');
            if (row && row.querySelector('td[aria-describedby="list_phieudieutri_GIOLAP_TDT"]')) {
                toggleRowCheckbox(row);
            }
        }, true);

        // Theo dõi chuột hover
        let hoveredRow = null;
        document.addEventListener('mouseover', function(e) {
            const row = e.target.closest('tr[role="row"]');
            if (row) hoveredRow = row;
        }, true);

        // Phím tắt Option + Shift + X và Option + Shift + P
        window.addEventListener('keydown', function(e) {
            if (e.altKey && e.shiftKey && e.code === 'KeyX') {
                e.preventDefault();
                if (hoveredRow) {
                    toggleRowCheckbox(hoveredRow);
                }
            }

            if (e.altKey && e.shiftKey && e.code === 'KeyP') {
                e.preventDefault();
                generateAndPrintPDT();
            }
        });

        // --- 1.2 CHÈN CỤM NÚT (IN & RESET) ĐỘC LẬP TRƯỚC "HỌ TÊN" ---
        function injectActionButtons() {
            if (document.getElementById('pdt-action-group')) return;

            const hoTenInput = document.getElementById('hoten');
            if (!hoTenInput) return;

            let targetInsertPoint = hoTenInput;
            let prev = hoTenInput.previousSibling;
            while (prev) {
                if (prev.nodeType === Node.ELEMENT_NODE && (prev.tagName === 'LABEL' || prev.textContent.includes('Họ tên') || prev.textContent.includes('họ tên'))) {
                    targetInsertPoint = prev;
                    break;
                }
                if (prev.nodeType === Node.TEXT_NODE && (prev.textContent.includes('Họ tên') || prev.textContent.includes('họ tên'))) {
                    targetInsertPoint = prev;
                    break;
                }
                prev = prev.previousSibling;
            }

            const container = document.createElement('span');
            container.id = 'pdt-action-group';
            container.style.display = 'inline-flex';
            container.style.alignItems = 'center';
            container.style.gap = '4px';
            container.style.marginRight = '8px';
            container.style.verticalAlign = 'middle';

            // Nút In - Tailwind Printer Icon
            const btnPrint = document.createElement('button');
            btnPrint.type = 'button';
            btnPrint.innerHTML = `
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="2" stroke="currentColor" style="width: 15px; height: 15px; display: block;">
                    <path stroke-linecap="round" stroke-linejoin="round" d="M6.72 13.829c-.24.03-.48.062-.72.096m.72-.096a42.415 42.415 0 0 1 10.56 0m-10.56 0L6.34 18m10.94-4.171c.24.03.48.062.72.096m-.72-.096L17.66 18m0 0 .229 2.523a1.125 1.125 0 0 1-1.12 1.227H7.231c-.662 0-1.18-.568-1.12-1.227L6.34 18m11.318 0h1.091A2.25 2.25 0 0 0 21 15.75V9.456c0-1.081-.768-2.015-1.837-2.175a48.055 48.055 0 0 0-1.913-.247M6.34 18H5.25A2.25 2.25 0 0 1 3 15.75V9.456c0-1.081.768-2.015 1.837-2.175a48.041 48.041 0 0 1 1.913-.247m10.5 0a48.536 48.536 0 0 0-10.5 0m10.5 0V3.375c0-.621-.504-1.125-1.125-1.125h-8.25c-.621 0-1.125.504-1.125 1.125v3.656h10.5Z" />
                </svg>`;
            btnPrint.style.cssText = 'display: inline-flex; align-items: center; justify-content: center; width: 26px; height: 26px; padding: 0; background: #0284c7; color: #ffffff; border: 1px solid #0369a1; border-radius: 4px; cursor: pointer; transition: background 0.15s;';
            btnPrint.onmouseenter = () => btnPrint.style.background = '#0369a1';
            btnPrint.onmouseleave = () => btnPrint.style.background = '#0284c7';
            btnPrint.onclick = (e) => {
                e.preventDefault();
                generateAndPrintPDT();
            };

            // Nút Reset - Tailwind ArrowPath Icon
            const btnReset = document.createElement('button');
            btnReset.type = 'button';
            btnReset.innerHTML = `
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="2" stroke="currentColor" style="width: 15px; height: 15px; display: block;">
                    <path stroke-linecap="round" stroke-linejoin="round" d="M16.023 9.348h4.992v-.001M2.985 19.644v-4.992m0 0h4.992m-4.993 0 3.181 3.183a8.25 8.25 0 0 0 13.803-3.7M4.031 9.865a8.25 8.25 0 0 1 13.803-3.7l3.181 3.182m0-4.991v4.99" />
                </svg>`;
            btnReset.style.cssText = 'display: inline-flex; align-items: center; justify-content: center; width: 26px; height: 26px; padding: 0; background: #f1f5f9; color: #475569; border: 1px solid #cbd5e1; border-radius: 4px; cursor: pointer; transition: background 0.15s;';
            btnReset.onmouseenter = () => btnReset.style.background = '#e2e8f0';
            btnReset.onmouseleave = () => btnReset.style.background = '#f1f5f9';
            btnReset.onclick = (e) => {
                e.preventDefault();
                const checkedBoxes = document.querySelectorAll('.final-tick-box, .injected-tick-box');
                checkedBoxes.forEach(cb => cb.remove());
            };

            container.appendChild(btnPrint);
            container.appendChild(btnReset);

            targetInsertPoint.parentNode.insertBefore(container, targetInsertPoint);
        }

        const buttonObserver = new MutationObserver(() => injectActionButtons());
        buttonObserver.observe(document.body, { childList: true, subtree: true });
        injectActionButtons();

        // --- 1.3 TRÍCH XUẤT VÀ XỬ LÝ DỮ LIỆU IN ---
        function getVal(selector) {
            const el = document.querySelector(selector);
            if (!el) return '';
            return (el.value !== undefined ? el.value : el.textContent || '').trim();
        }

        function getCellText(row, ariaName) {
            const td = row.querySelector(`td[aria-describedby="${ariaName}"]`);
            if (!td) return '';
            const raw = td.getAttribute('title') || td.textContent || '';
            return raw.replace(/\u00a0/g, ' ').trim();
        }

        function parseDateToNumber(dateStr, timeStr) {
            if (!dateStr) return 0;
            const [d, m, y] = dateStr.split('/').map(Number);
            let h = 0, mi = 0, s = 0;
            if (timeStr) {
                const parts = timeStr.split(':').map(Number);
                h = parts[0] || 0;
                mi = parts[1] || 0;
                s = parts[2] || 0;
            }
            return new Date(y, m - 1, d, h, mi, s).getTime();
        }

        function generateAndPrintPDT() {
            const checkedBoxes = Array.from(document.querySelectorAll('tr[role="row"] .final-tick-box:checked, tr[role="row"] .injected-tick-box:checked'));
            if (checkedBoxes.length === 0) {
                alert('Chưa có hàng nào được tick chọn. Hãy nhấp đúp vào hàng hoặc dùng Option + Shift + X!');
                return;
            }

            const hoTen = getVal('#hoten') || 'CHƯA CÓ TÊN';
            const tuoi = getVal('#tuoi') || '';

            const genderEl = document.getElementById('gioitinh');
            let genderText = '';
            if (genderEl) {
                genderText = genderEl.options && genderEl.selectedIndex >= 0 ? genderEl.options[genderEl.selectedIndex].text : genderEl.value;
            }
            const isNam = genderText.toLowerCase().includes('nam');
            const isNu = genderText.toLowerCase().includes('nữ') || genderText.toLowerCase().includes('nu');

            let benhChinh = '';
            const icdKhoa = getVal('#icdkhoadt'), tenKhoa = getVal('#tenicdkhoadt');
            const icdSoBo = getVal('#icdsobo'), tenSoBo = getVal('#tenicdsobo');
            const icd2 = getVal('#icd2'), tenNguyenNhan = getVal('#icdnguyennhan');

            if (icdKhoa || tenKhoa) {
                benhChinh = [icdKhoa, tenKhoa].filter(Boolean).join(' - ');
            } else if (icdSoBo || tenSoBo) {
                benhChinh = [icdSoBo, tenSoBo].filter(Boolean).join(' - ');
            } else if (icd2 || tenNguyenNhan) {
                benhChinh = [icd2, tenNguyenNhan].filter(Boolean).join(' - ');
            }

            const icdPhu = getVal('#icd_benhphu');
            const tenPhu = getVal('#benhphu');
            let benhPhu = '';
            if (icdPhu || tenPhu) {
                benhPhu = [icdPhu, tenPhu].filter(Boolean).join(' - ');
            }

            let chanDoanFull = benhChinh;
            if (benhPhu) {
                chanDoanFull += (chanDoanFull ? ' - ' : '') + benhPhu;
            }

            const icdPB = getVal('#icd_phanbiet');
            const tenPB = getVal('#tenicd_phanbiet');
            const chanDoanPB = (icdPB || tenPB) ? [icdPB, tenPB].filter(Boolean).join(' - ') : '';

            const soVaoVien = getVal('#patient-info #mabenhan') || getVal('#mabenhan') || '';
            let maNguoiBenh = '';
            const maNbTd = document.querySelector('td[aria-describedby="list_benhnhan_MA_BENH_NHAN"]');
            if (maNbTd) {
                maNguoiBenh = (maNbTd.getAttribute('title') || maNbTd.textContent || '').trim();
            }

            const phong = getVal('#tdt_sobuong');
            const giuong = getVal('#tdt_sogiuong');

            const rowsData = [];
            checkedBoxes.forEach(cb => {
                const row = cb.closest('tr[role="row"]');
                if (!row) return;

                const ngayLap = getCellText(row, 'list_phieudieutri_NGAY_LAP');
                let gioLap = getCellText(row, 'list_phieudieutri_GIOLAP_TDT');
                if (gioLap.split(':').length === 3) {
                    gioLap = gioLap.substring(0, 5);
                }

                const dienBien = getCellText(row, 'list_phieudieutri_TDT_DIENBIENBENH');

                let yLenh = getCellText(row, 'list_phieudieutri_TDT_YLENH');
                if (!yLenh) {
                    yLenh = getCellText(row, 'list_phieudieutri_YLENH_TONGHOP');
                    yLenh = yLenh.replace(/Buồng:.*$/m, '').replace(/Y lệnh khác:/g, '').trim();
                }

                let bsDieuTri = getCellText(row, 'list_phieudieutri_TEN_BS_DIEUTRI');
                if (bsDieuTri && !bsDieuTri.toLowerCase().startsWith('bs')) {
                    bsDieuTri = 'BSCKI. ' + bsDieuTri;
                }

                const khoa = getCellText(row, 'list_phieudieutri_TEN_PHONGBAN') || 'Khoa Chống độc';
                const timestamp = parseDateToNumber(ngayLap, gioLap);

                rowsData.push({
                    ngayLap,
                    gioLap,
                    dienBien,
                    yLenh,
                    bsDieuTri,
                    khoa,
                    timestamp
                });
            });

            rowsData.sort((a, b) => a.timestamp - b.timestamp);
            const tenKhoaHeader = rowsData[0]?.khoa || 'Khoa Chống độc';

            const pagesData = [];
            let curIndex = 0;
            let pageNum = 1;

            while (curIndex < rowsData.length) {
                const isOdd = (pageNum % 2 !== 0);
                const limit = isOdd ? 7 : 14;
                const chunk = rowsData.slice(curIndex, curIndex + limit);
                pagesData.push({
                    pageNum: pageNum,
                    isOdd: isOdd,
                    rows: chunk
                });
                curIndex += limit;
                pageNum++;
            }

            function renderHeaderBlock() {
                return `
                <table class="header-table">
                    <tr>
                        <td class="hospital-info">
                            <div class="name">BỆNH VIỆN ĐA KHOA KIÊN GIANG</div>
                            <div>${tenKhoaHeader}</div>
                        </td>
                        <td class="title-info">
                            <h1>PHIẾU THEO DÕI<br>ĐIỀU TRỊ</h1>
                            <div style="margin-top: 4px; font-size: 11pt;">Tờ số: ...........</div>
                        </td>
                        <td class="meta-info">
                            <div>MS: 36/BV2</div>
                            <div>Số vào viện: ${soVaoVien}</div>
                            <div>Mã người bệnh: ${maNguoiBenh}</div>
                        </td>
                    </tr>
                </table>

                <div class="patient-info">
                    <div class="row">
                        <div style="flex: 1;">
                            Họ và tên người bệnh: <span class="patient-name-val">${hoTen}</span>
                        </div>
                        <div style="width: 220px;">
                            Tuổi: ${tuoi} 
                            <span class="checkbox-box">${isNam ? 'X' : '&nbsp;'}</span> Nam 
                            <span class="checkbox-box">${isNu ? 'X' : '&nbsp;'}</span> Nữ
                        </div>
                    </div>
                    <div class="row">
                        <div style="width: 240px;">Khoa: ${tenKhoaHeader}</div>
                        <div style="width: 160px;">Phòng : ${phong}</div>
                        <div style="flex: 1;">Giường: ${giuong}</div>
                    </div>
                    <div class="row">
                        <div style="flex: 1;">
                            Chẩn đoán: ${chanDoanFull}
                        </div>
                    </div>
                    <div class="row">
                        <div style="flex: 1;">Chẩn đoán phân biệt: ${chanDoanPB}</div>
                    </div>
                </div>`;
            }

            let fullPagesHtml = '';
            pagesData.forEach(p => {
                let rowsHtml = '';
                const rows = p.rows;
                const uniqueDaysInChunk = new Set(rows.map(r => r.ngayLap));
                const hasMultipleDays = uniqueDaysInChunk.size > 1;

                for (let i = 0; i < rows.length; i++) {
                    const cur = rows[i];
                    const next = rows[i + 1];
                    const needBorderBottom = hasMultipleDays && next && (next.ngayLap !== cur.ngayLap);
                    const rowClass = needBorderBottom ? 'row-day-divider' : 'row-same-day';

                    rowsHtml += `
                        <tr class="${rowClass}">
                            <td class="col-time">
                                <div>${cur.ngayLap}</div>
                                <div style="margin-top: 3px;">${cur.gioLap}</div>
                            </td>
                            <td class="col-progress">${cur.dienBien}</td>
                            <td class="col-orders">
                                <div class="order-content">${cur.yLenh}</div>
                                <div class="signature-block">
                                    <div class="signature-title">Bác sĩ điều trị</div>
                                    <div class="signature-name">${cur.bsDieuTri}</div>
                                </div>
                            </td>
                        </tr>
                    `;
                }

                fullPagesHtml += `
                <div class="page ${p.isOdd ? 'odd-page' : 'even-page'}">
                    ${p.isOdd ? renderHeaderBlock() : ''}

                    <table class="treatment-table">
