  // ================= 6. KHÓA CHẶT ĐÓNG MODAL EDIT =================
  function closeEditModal() {
    editOverlay.classList.remove('is-active');
    currentEditingAccount = null;
    currentEditingKey = null;
    delete editModalCard.dataset.accountKey;
    editVerifyPassInput.value = '';
