  // ================= 7. XỬ LÝ VẼ, DRAG & ZOOM TRÊN CANVAS =================
  function drawCanvas() {
    const ctx = avatarCanvas.getContext('2d');
    const cw = avatarCanvas.width;
    const ch = avatarCanvas.height;
    ctx.clearRect(0, 0, cw, ch);

    if (!canvasImg) {
      ctx.fillStyle = "#0284c7";
      ctx.fillRect(0, 0, cw, ch);
      ctx.fillStyle = "#ffffff";
      ctx.font = "bold 36px sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText("?", cw / 2, ch / 2);
      return;
    }

    ctx.save();
    const drawW = canvasImg.width * imgState.scale;
    const drawH = canvasImg.height * imgState.scale;

    const minX = cw - drawW;
    const minY = ch - drawH;

    if (imgState.x > 0) imgState.x = 0;
    if (imgState.x < minX) imgState.x = minX;
    if (imgState.y > 0) imgState.y = 0;
    if (imgState.y < minY) imgState.y = minY;

    ctx.drawImage(canvasImg, imgState.x, imgState.y, drawW, drawH);
    ctx.restore();
  }

  function setupNewImage(img) {
    canvasImg = img;
    const cw = avatarCanvas.width;
    const ch = avatarCanvas.height;

    const scaleX = cw / img.width;
    const scaleY = ch / img.height;
    imgState.minScale = Math.max(scaleX, scaleY);
    imgState.scale = imgState.minScale;

    imgState.x = (cw - img.width * imgState.scale) / 2;
    imgState.y = (ch - img.height * imgState.scale) / 2;

    zoomSlider.min = imgState.minScale;
    zoomSlider.max = imgState.minScale * 3.5;
    zoomSlider.value = imgState.scale;

    drawCanvas();
  }

  function loadSourceToCanvas(src) {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => setupNewImage(img);
    img.onerror = () => {
      canvasImg = null;
      drawCanvas();
    };
    img.src = src;
  }

  avatarDropzone.addEventListener('mousedown', (e) => {
    if (!canvasImg) return;
    isDragging = true;
    dragStart = { x: e.clientX - imgState.x, y: e.clientY - imgState.y };
  });

  window.addEventListener('mousemove', (e) => {
    if (!isDragging) return;
    imgState.x = e.clientX - dragStart.x;
    imgState.y = e.clientY - dragStart.y;
    drawCanvas();
  });

  window.addEventListener('mouseup', () => { isDragging = false; });

  avatarDropzone.addEventListener('wheel', (e) => {
    if (!canvasImg) return;
    e.preventDefault();
    const zoomDelta = e.deltaY < 0 ? 0.08 : -0.08;
    let newScale = imgState.scale + zoomDelta;
    if (newScale < imgState.minScale) newScale = imgState.minScale;
    if (newScale > imgState.minScale * 3.5) newScale = imgState.minScale * 3.5;

    const cx = avatarCanvas.width / 2;
    const cy = avatarCanvas.height / 2;
    imgState.x = cx - (cx - imgState.x) * (newScale / imgState.scale);
    imgState.y = cy - (cy - imgState.y) * (newScale / imgState.scale);
    imgState.scale = newScale;

    zoomSlider.value = newScale;
    drawCanvas();
  });

  zoomSlider.addEventListener('input', (e) => {
    if (!canvasImg) return;
    const newScale = parseFloat(e.target.value);
    const cx = avatarCanvas.width / 2;
    const cy = avatarCanvas.height / 2;
    imgState.x = cx - (cx - imgState.x) * (newScale / imgState.scale);
    imgState.y = cy - (cy - imgState.y) * (newScale / imgState.scale);
    imgState.scale = newScale;
    drawCanvas();
  });

  function handleImageFile(file) {
    if (!file || !file.type.startsWith('image/')) {
      alert('Vui lòng chọn tệp hình ảnh!');
      return;
    }
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => setupNewImage(img);
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  }

  btnPickFile.addEventListener('click', () => avatarFileInput.click());
  avatarFileInput.addEventListener('change', (e) => {
    if (e.target.files && e.target.files[0]) handleImageFile(e.target.files[0]);
  });

  avatarDropzone.addEventListener('dragover', (e) => { e.preventDefault(); });
  avatarDropzone.addEventListener('drop', (e) => {
    e.preventDefault();
    if (e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleImageFile(e.dataTransfer.files[0]);
    }
  });

  function exportCroppedAvatar() {
    const outCanvas = document.createElement('canvas');
    outCanvas.width = 96;
    outCanvas.height = 96;
    const outCtx = outCanvas.getContext('2d');
    outCtx.imageSmoothingEnabled = true;
    outCtx.imageSmoothingQuality = 'high';
    outCtx.drawImage(avatarCanvas, 0, 0, 96, 96);
    return outCanvas.toDataURL('image/jpeg', 0.82);
  }

  // ================= 8. QUẢN LÝ MỞ MODAL SỬA & TẠO MỚI =================
  function openEditModal(key, acc) {
    currentEditingKey = key || acc.id || '';
    currentEditingAccount = { ...acc, key: currentEditingKey };
    editModalCard.dataset.accountKey = currentEditingKey;

    editUserBadge.textContent = `@${acc.accountname}`;
