    editUsernameInput.value = acc.username || '';
    editVerifyPassInput.value = '';
    btnDeleteAcc.style.display = 'block';

    const initialAvatar = acc.avatar || `https://ui-avatars.com/api/?name=${encodeURIComponent(acc.username || acc.accountname)}&background=0284c7&color=fff&size=104`;
    loadSourceToCanvas(initialAvatar);

    editOverlay.classList.add('is-active');
