                background: #f8fafc;
                display: flex;
                flex-direction: column;
                gap: 5px;
            }
            .rm-patient-item-detail {
                font-size: 11px;
                color: #0f172a;
                padding: 5px 8px;
                background: #ffffff;
                border-radius: 5px;
                border-left: 3px solid #0066cc;
                border: 1px solid #cbd5e1;
                line-height: 1.35;
                word-break: break-word;
            }
            .rm-patient-item-detail.is-current {
                background: #fef08a !important;
                border-left: 3px solid #ca8a04 !important;
                border-color: #fde047 !important;
                color: #854d0e !important;
                font-weight: 700;
            }
        `;
        (document.head || document.documentElement).appendChild(style);
    }

    // 4. Đồng bộ độ rộng cột theo cơ chế jqGrid
    function syncJqGridColumnWidth(targetWidth) {
        if (!targetWidth || Math.abs(targetWidth - lastAppliedWidth) < 2) return;
        lastAppliedWidth = targetWidth;

        const $ = window.$ || window.jQuery;
        if ($ && $.fn && $.fn.jqGrid) {
            try {
                const $grid = $(`#${TARGET_GRID_ID}`);
                if ($grid.length && $grid[0].grid) {
                    if (typeof $grid.jqGrid('setColWidth') === 'function') {
                        $grid.jqGrid('setColWidth', BED_COL_NAME, targetWidth, true);
                        return;
                    }
                }
            } catch (e) {}
        }

        const thHeader = document.getElementById(BED_HEADER_ID);
        if (!thHeader) return;

        const colIndex = Array.from(thHeader.parentNode.children).indexOf(thHeader) + 1;
        if (colIndex <= 0) return;

        thHeader.style.width = `${targetWidth}px`;
        const innerDiv = thHeader.querySelector('div');
        if (innerDiv) innerDiv.style.width = `${targetWidth}px`;

        const firstRowCell = document.querySelector(`table#${TARGET_GRID_ID} tr.jqgfirstrow td:nth-child(${colIndex})`);
        if (firstRowCell) {
            firstRowCell.style.width = `${targetWidth}px`;
        }

        const headerCol = document.querySelector(`.ui-jqgrid-htable colgroup col:nth-child(${colIndex})`);
        if (headerCol) headerCol.style.width = `${targetWidth}px`;

        const bodyCol = document.querySelector(`table#${TARGET_GRID_ID} colgroup col:nth-child(${colIndex})`);
        if (bodyCol) bodyCol.style.width = `${targetWidth}px`;

        const bodyCells = document.querySelectorAll(`table#${TARGET_GRID_ID} tr.jqgrow td:nth-child(${colIndex})`);
        bodyCells.forEach(cell => {
            cell.style.width = `${targetWidth}px`;
        });
    }

    function autoFitBedColumn() {
        const grid = document.getElementById(TARGET_GRID_ID);
        if (!grid) return;

        const cells = grid.querySelectorAll(`tr.jqgrow ${BED_CELL_SELECTOR}`);
        if (!cells.length) return;

        let maxCalculated = 125;
        cells.forEach(cell => {
            const badge = cell.querySelector('.his-room-badge');
            const badgeWidth = badge ? badge.offsetWidth : 0;
            const originalContent = (cell.textContent || '').replace(badge ? badge.textContent : '', '').trim();
            const estimated = badgeWidth + (originalContent.length * 7.5) + 28;
            if (estimated > maxCalculated) {
                maxCalculated = estimated;
            }
        });

        syncJqGridColumnWidth(Math.ceil(maxCalculated));
    }

    // 5. Trích xuất dữ liệu bệnh nhân từ dòng
    function extractPatientFromRow(tr) {
        const sbaCell = tr.querySelector('td[aria-describedby*="SOBENHAN_HT"]');
        const nameCell = tr.querySelector('td[aria-describedby*="TEN_BENH_NHAN_HT"]');
        const ageCell = tr.querySelector('td[aria-describedby*="NGAY_SINH"]');
        const genderCell = tr.querySelector('td[aria-describedby*="GIOI_TINH"]');
        const addrCell = tr.querySelector('td[aria-describedby*="DIA_CHI"]');
        const dischargeCell = tr.querySelector(DISCHARGE_DATE_SELECTOR);

        const sba = sbaCell ? sbaCell.textContent.trim() : '';
        const fullname = nameCell ? (nameCell.textContent || '').trim() : '';
        const age = ageCell ? ageCell.textContent.trim() : '';
        const gender = genderCell ? genderCell.textContent.trim() : '';
        const address = addrCell ? (addrCell.getAttribute('title') || addrCell.textContent || '').trim() : '';
        const ngayravien = dischargeCell ? dischargeCell.textContent.trim() : '';

        return { sba, fullname, age, gender, address, ngayravien };
    }

    function scanActivePatientsFromGrid() {
        const grid = document.getElementById(TARGET_GRID_ID);
        if (!grid) return [];

        const activePatients = [];
        const rows = grid.querySelectorAll('tr.jqgrow');
        rows.forEach(tr => {
            const pInfo = extractPatientFromRow(tr);
            if (pInfo.sba) {
                const cloudRecord = patientsRoomMap[pInfo.sba];
                if (cloudRecord && cloudRecord.roomname) {
                    pInfo.roomname = cloudRecord.roomname;
                }
                activePatients.push(pInfo);
            }
        });
        return activePatients;
    }

    // 6. Tự động dọn dẹp các bản ghi quá hạn trên Firebase
    async function cleanupExpiredPatients() {
        const gridPatients = scanActivePatientsFromGrid();
        const activeSbaSet = new Set(gridPatients.map(p => p.sba));
        const now = Date.now();
        const MS_PER_DAY = 24 * 60 * 60 * 1000;

        for (const [sba, record] of Object.entries(patientsRoomMap)) {
            if (!record || !record.id) continue;
            let shouldDelete = false;

            // ĐIỀU KIỆN 1: Đã xuất viện quá 30 ngày
            if (record.ngayravien && record.ngayravien.trim().length > 2) {
                const dischargeDate = parseDischargeDate(record.ngayravien);
                let dischargeTimestamp = dischargeDate ? dischargeDate.getTime() : null;

                // Nếu không parse được chuỗi ngày, dùng timeupdate làm mốc thay thế
                if (!dischargeTimestamp && record.timeupdate) {
                    dischargeTimestamp = new Date(record.timeupdate).getTime();
                }

                if (dischargeTimestamp && (now - dischargeTimestamp) >= (30 * MS_PER_DAY)) {
                    shouldDelete = true;
                }
            }

            // ĐIỀU KIỆN 2: Quá 60 ngày kể từ timeupdate mà không xuất hiện trong Grid list
            if (!shouldDelete && record.timeupdate) {
                const updateTimestamp = new Date(record.timeupdate).getTime();
                if (!isNaN(updateTimestamp) && (now - updateTimestamp) >= (60 * MS_PER_DAY)) {
                    if (!activeSbaSet.has(sba)) {
                        shouldDelete = true;
                    }
                }
            }

            // Thực hiện xóa ngầm khỏi Firebase nếu thỏa điều kiện
            if (shouldDelete) {
                try {
                    const deleteUrl = `${DB_BASE_URL}/${FOLDER_NAME}/${record.id}.json?auth=${DB_SECRET}`;
                    fetch(deleteUrl, { method: 'DELETE' }).catch(() => {});
                    delete patientsRoomMap[sba];
                } catch (e) {}
            }
        }
    }

    // 7. Nạp dữ liệu Firebase
    async function fetchPatientsDatabase() {
        if (!document.getElementById(TARGET_GRID_ID)) return;

        try {
            const res = await fetch(FIREBASE_ENDPOINT);
            if (res.ok) {
                const data = await res.json();
                patientsRoomMap = {};
                if (data && typeof data === 'object') {
                    Object.values(data).forEach(item => {
                        if (item && item.sba) {
                            patientsRoomMap[item.sba] = item;
                        }
                    });
                }
                renderBadgesOnGrid();
                // Kích hoạt dọn dẹp các bản ghi quá hạn ngầm
                cleanupExpiredPatients();
            }
        } catch (e) {
            console.warn('[RoomManager] Chưa thể kết nối Firebase lúc này:', e.message);
        }
    }

    // 8. Render nhãn phòng trên bảng HIS
    function renderBadgesOnGrid() {
        const grid = document.getElementById(TARGET_GRID_ID);
        if (!grid) return;

        const rows = grid.querySelectorAll('tr.jqgrow');
        rows.forEach(tr => {
            const bedCell = tr.querySelector(BED_CELL_SELECTOR);
            if (!bedCell) return;

            const sbaCell = tr.querySelector('td[aria-describedby*="SOBENHAN_HT"]');
            const sba = sbaCell ? sbaCell.textContent.trim() : '';
            if (!sba) return;

            let badge = bedCell.querySelector('.his-room-badge');
            if (!badge) {
                badge = document.createElement('span');
                badge.className = 'his-room-badge';
                bedCell.insertBefore(badge, bedCell.firstChild);
            }

            const ptData = patientsRoomMap[sba];
            const roomName = (ptData && ptData.roomname) ? ptData.roomname : null;

            if (roomName) {
                badge.textContent = roomName;
                badge.className = 'his-room-badge assigned';
                badge.title = `Phòng: ${roomName} (Click mở sơ đồ phân phòng)`;
            } else {
                badge.textContent = '+ Phòng';
                badge.className = 'his-room-badge unassigned';
                badge.title = `Chưa gán phòng (Click mở sơ đồ phân phòng)`;
            }
        });

        autoFitBedColumn();
    }

    // 9. Quản lý Modal
    function createModalDOM() {
        if (document.getElementById('room-manager-modal')) return;

        const backdrop = document.createElement('div');
        backdrop.id = 'room-manager-modal';
        backdrop.className = 'rm-modal-backdrop';
        backdrop.innerHTML = `
            <div class="rm-modal-card">
                <div class="rm-modal-header">
                    <div class="rm-modal-title">
                        <h3>SƠ ĐỒ PHÂN PHÒNG ĐIỀU TRỊ</h3>
                        <div id="rm-target-info" class="patient-target-tag"></div>
                    </div>
                    <button type="button" class="rm-modal-close-btn" id="rm-btn-close" title="Đóng">&times;</button>
                </div>
                <div class="rm-modal-body" id="rm-modal-grids-container"></div>
            </div>
        `;
        document.body.appendChild(backdrop);

        document.getElementById('rm-btn-close').addEventListener('click', closeModal);
    }

    function openModal(patientInfo) {
        activeTargetPatient = patientInfo;
        const targetTag = document.getElementById('rm-target-info');
        if (targetTag) {
            targetTag.textContent = `${patientInfo.fullname} (${patientInfo.age || 'N/A'}) - SBA: ${patientInfo.sba}`;
        }
        removeFloatingDetail();
        renderRoomSchedules();
        const modal = document.getElementById('room-manager-modal');
        if (modal) modal.classList.add('open');
    }

    function closeModal() {
        removeFloatingDetail();
        const modal = document.getElementById('room-manager-modal');
        if (modal) modal.classList.remove('open');
        activeTargetPatient = null;
    }

    function removeFloatingDetail() {
        const existing = document.getElementById('rm-floating-detail-panel');
        if (existing) existing.remove();
        currentFloatingRoomCode = null;
    }

    function openFloatingDetail(holderElement, roomCode, patientList) {
        removeFloatingDetail();
        currentFloatingRoomCode = roomCode;

        const container = document.getElementById('rm-modal-grids-container');
        if (!container) return;

        const holderRect = holderElement.getBoundingClientRect();
        const containerRect = container.getBoundingClientRect();

        const floating = document.createElement('div');
        floating.id = 'rm-floating-detail-panel';
        floating.className = 'rm-floating-detail';
        floating.setAttribute('data-roomcode', roomCode);

        const displayHeader = cleanRoomHeader(roomCode);
        const areaName = getAreaName(roomCode);

        let listHTML = '';
        if (patientList.length === 0) {
            listHTML = `<div class="rm-empty-state-compact">Phòng hiện đang trống</div>`;
        } else {
            patientList.forEach(p => {
                const isSelected = activeTargetPatient && (p.sba === activeTargetPatient.sba);
                listHTML += `
                    <div class="rm-patient-item-detail ${isSelected ? 'is-current' : ''}">
                        <strong>${p.fullname}</strong> - ${p.age ? p.age.split('/').pop() : 'N/A'} - ${p.sba}
                    </div>
                `;
            });
        }

        floating.innerHTML = `
            <div class="rm-floating-header">
                <span class="rm-floating-header-title" title="Phòng: ${displayHeader} (${areaName})">Phòng: ${displayHeader} (${areaName})</span>
                <div class="rm-floating-actions">
                    <button type="button" class="rm-floating-btn-pick" id="rm-btn-pick-room" title="Chọn phòng này cho bệnh nhân">+</button>
                    <button type="button" class="rm-floating-close-btn" id="rm-btn-close-floating" title="Thu gọn">&times;</button>
                </div>
            </div>
            <div class="rm-floating-body" id="rm-floating-body-list">
                ${listHTML}
            </div>
        `;

        container.appendChild(floating);

        const panelWidth = floating.offsetWidth || 340;
        let top = (holderRect.top - containerRect.top) + container.scrollTop;
        let left = (holderRect.left - containerRect.left) + container.scrollLeft;

        if ((left + panelWidth + 10) > container.clientWidth) {
            left = container.clientWidth - panelWidth - 15;
        }

        floating.style.top = `${top}px`;
        floating.style.left = `${left}px`;

        document.getElementById('rm-btn-pick-room').addEventListener('click', (e) => {
            e.stopPropagation();
            handleAssignRoom(roomCode, holderElement);
        });

        document.getElementById('rm-btn-close-floating').addEventListener('click', (e) => {
            e.stopPropagation();
            removeFloatingDetail();
        });
    }

    // 10. Render danh sách phòng
    function renderRoomSchedules() {
        const container = document.getElementById('rm-modal-grids-container');
        if (!container) return;
        container.innerHTML = '';

        const gridPatients = scanActivePatientsFromGrid();

        const currentInRooms = {};
        gridPatients.forEach(pt => {
            const isDischarged = pt.ngayravien && pt.ngayravien.length > 2;
            if (pt.roomname && !isDischarged) {
                if (!currentInRooms[pt.roomname]) currentInRooms[pt.roomname] = [];
                currentInRooms[pt.roomname].push(pt);
            }
        });

        Object.keys(SCHEMAS).forEach(key => {
            const schema = SCHEMAS[key];

            let totalPatientsInArea = 0;
            schema.rooms.forEach(r => {
                if (r && currentInRooms[r]) totalPatientsInArea += currentInRooms[r].length;
            });

            const section = document.createElement('div');
            section.className = 'rm-section-box';

            section.innerHTML = `
                <div class="rm-section-title">
                    <span>${schema.title}</span>
                    <span class="badge-count">${totalPatientsInArea} bệnh nhân đang nằm</span>
                </div>
                <div class="rm-rooms-grid" id="grid-${key}"></div>
            `;

            container.appendChild(section);
            const gridContainer = document.getElementById(`grid-${key}`);

            schema.rooms.forEach(roomCode => {
                const cell = document.createElement('div');

                if (roomCode === null) {
                    cell.className = 'rm-empty-holder';
                } else {
                    const list = currentInRooms[roomCode] || [];
                    cell.className = 'rm-room-holder';
                    cell.setAttribute('data-roomcode', roomCode);

                    const displayHeader = cleanRoomHeader(roomCode);

                    let compactListHTML = '';
                    if (list.length === 0) {
                        compactListHTML = `<div class="rm-empty-state-compact">Trống</div>`;
                    } else {
                        list.slice(0, 2).forEach(p => {
                            compactListHTML += `
                                <div class="rm-patient-compact-text">
                                    • <strong>${p.fullname}</strong>
                                </div>
                            `;
                        });
                        if (list.length > 2) {
                            compactListHTML += `<div class="rm-patient-compact-text" style="color:#0066cc;font-weight:700;">+ ${list.length - 2} BN khác...</div>`;
                        }
                    }

                    cell.innerHTML = `
                        <div class="rm-holder-header">
                            <span>${displayHeader}</span>
                            <span class="rm-holder-count">${list.length}</span>
                        </div>
                        <div class="rm-holder-list-compact">
                            ${compactListHTML}
                        </div>
                    `;

                    cell.addEventListener('click', (e) => {
                        e.stopPropagation();
                        openFloatingDetail(cell, roomCode, list);
                    });
                }

                gridContainer.appendChild(cell);
            });
        });
    }

    // 11. Gán phòng & Cập nhật dữ liệu (Bổ sung timeupdate)
    async function handleAssignRoom(targetRoomName, holderElement) {
        if (!activeTargetPatient) return;

        const sba = activeTargetPatient.sba;
        let existingRecord = patientsRoomMap[sba];
        const patientId = (existingRecord && existingRecord.id) ? existingRecord.id : generateUUID();

        // Cập nhật timestamp hiện tại theo chuẩn ISO string
        const currentTimestamp = new Date().toISOString();

        const updatedData = {
            id: patientId,
            sba: sba,
            fullname: activeTargetPatient.fullname,
            age: activeTargetPatient.age,
            gender: activeTargetPatient.gender,
            address: activeTargetPatient.address,
            ngayravien: activeTargetPatient.ngayravien || '',
            roomname: targetRoomName,
            timeupdate: currentTimestamp // Lưu mốc thời gian cập nhật phòng
        };

        // 1. Cập nhật cache cục bộ tức thì
        patientsRoomMap[sba] = updatedData;

        // 2. Cập nhật nhãn bên ngoài Grid HIS
        renderBadgesOnGrid();

        // 3. Render lại các ô sơ đồ
        renderRoomSchedules();

        // 4. Cập nhật lại danh sách bên trong bảng mở rộng đang xem
        const newHolderEl = document.querySelector(`.rm-room-holder[data-roomcode="${targetRoomName}"]`) || holderElement;
        const gridPatients = scanActivePatientsFromGrid();
        const updatedList = gridPatients.filter(pt => {
            const isDischarged = pt.ngayravien && pt.ngayravien.length > 2;
            return pt.roomname === targetRoomName && !isDischarged;
        });

        openFloatingDetail(newHolderEl, targetRoomName, updatedList);

        // 5. Lưu bất đồng bộ ngầm lên Firebase
        try {
            const recordEndpoint = `${DB_BASE_URL}/${FOLDER_NAME}/${patientId}.json?auth=${DB_SECRET}`;
            await fetch(recordEndpoint, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(updatedData)
            });
        } catch (err) {
            console.error('[RoomManager] Lỗi lưu Firebase:', err);
        }
    }

    // 12. Bắt sự kiện Click mở Modal
    function bindGridEvents() {
        document.addEventListener('click', function(e) {
            const badge = e.target.closest(`table#${TARGET_GRID_ID} tr.jqgrow ${BED_CELL_SELECTOR} .his-room-badge`);
            if (!badge) return;

            e.preventDefault();
            e.stopPropagation();

            const tr = badge.closest('tr');
            if (!tr) return;

            const pInfo = extractPatientFromRow(tr);
            if (!pInfo.sba) return;

            openModal(pInfo);
        }, true);
    }

    // 13. MutationObserver: Chỉ khởi tạo khi tìm thấy bảng #list_benhnhan
    function startObserver() {
        if (observer) return;
        observer = new MutationObserver(() => {
            const grid = document.getElementById(TARGET_GRID_ID);
            if (grid) {
                if (!isInitialized) {
                    isInitialized = true;
                    injectStyles();
                    createModalDOM();
                    bindGridEvents();
                    fetchPatientsDatabase();
                }
                clearTimeout(resizeDebounce);
                resizeDebounce = setTimeout(() => {
                    renderBadgesOnGrid();
                }, 120);
            }
        });
        observer.observe(document.body, { childList: true, subtree: true });
    }

    function bootstrap() {
        startObserver();
        if (document.getElementById(TARGET_GRID_ID)) {
            isInitialized = true;
            injectStyles();
            createModalDOM();
            bindGridEvents();
            fetchPatientsDatabase();
        }
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', bootstrap);
    } else {
        bootstrap();
    }
})();
